<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage45Api,FundsOrder} from '../../../business-common/stage45/types'
import {money,date,label} from '../../../business-common/stage45/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
const props=defineProps<{api:Stage45Api;id:string;refreshKey?:number}>(),data=ref<FundsOrder|null>(null),loading=ref(false),error=ref('');let ticket=0
async function load(){if(!props.id)return;const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{const value=await props.api.read<FundsOrder>('/orders/'+props.id+'/funds');if(run===ticket&&owner===props.api.owner())data.value=value}catch(e){if(run===ticket){data.value=null;error.value=e instanceof Error?e.message:'资金详情读取失败。'}}finally{if(run===ticket)loading.value=false}}
function openSale(id:string){uni.navigateTo({url:'/pages/after-sale/detail/index?id='+id})}
watch(()=>[props.id,props.api.owner()],()=>{ticket++;data.value=null;load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;data.value=null})
</script>
<template><view class="s45"><BaseCard v-if="error"><text class="error" role="alert">{{error}}</text><AppButton class="s45-action" @click="load">重新读取</AppButton></BaseCard><text v-if="loading&&!data" class="state">正在读取订单资金…</text><template v-if="data"><view class="hero"><text class="hero-title">{{data.storeName}}</text><text>订单 {{data.orderSn}}</text><text class="hero-meta">{{label(data.mode)}} · {{data.currency}}</text></view><BaseCard><text class="section">原交易与历史规则</text><view class="row"><text>商品金额 G</text><text>¥{{money(data.goodsCent)}}</text></view><view class="row"><text>固定履约费用 F</text><text>¥{{money(data.freightCent)}}</text></view><view class="row"><text>可信实付 P</text><text>{{data.paidCent==null?'待核实':'¥'+money(data.paidCent)}}</text></view><template v-if="data.snapshot"><view class="row"><text>原佣金比例</text><text>{{data.snapshot.rateBps==null?'待核实':(data.snapshot.rateBps/100).toFixed(2)+'%'}}</text></view><text class="muted">规则版本 {{data.snapshot.ruleRevision}} · 原始佣金 ¥{{money(data.snapshot.originalCommissionCent)}}</text><text class="muted">商品款计佣，固定履约费不计佣；当前规则不改写历史。</text></template></BaseCard>
<BaseCard><text class="section">可信实际资金</text><view class="summary"><view class="metric"><text class="muted">商品已退</text><text>¥{{money(data.goodsRefundCent)}}</text></view><view class="metric"><text class="muted">独立费用已退</text><text>¥{{money(data.feeRefundCent)}}</text></view><view class="metric"><text class="muted">实际分账</text><text>¥{{money(data.sharedCent)}}</text></view><view class="metric"><text class="muted">实际回退</text><text>¥{{money(data.returnedCent)}}</text></view></view><view class="row"><text>实际净佣金</text><text>¥{{money(data.actualCommissionCent)}}</text></view><view class="row"><text>当前商品佣金目标（测算）</text><text>¥{{money(data.targetCommissionCent)}}</text></view><view class="row"><text>本订单实际净额</text><text class="price">{{data.netCent==null?'待核实':'¥'+money(data.netCent)}}</text></view><text class="notice">{{data.basis}}</text><text class="muted">手续费：{{data.feeCent==null?'待核对，尚无有效费用证据':'¥'+money(data.feeCent)}}</text><text class="muted">{{data.finished?'已取得独立完结／解冻结果':'尚未取得完结／解冻成功结果'}}；{{data.pendingObligationCent?'仍有退款义务处理中':'各项最终状态见下方明细'}}。</text></BaseCard>
<BaseCard v-if="data.obligations?.length"><text class="section">商品与独立费用义务</text><view v-for="row in data.obligations" :key="row.id" class="record"><view class="row"><text>{{label(row.kind)}}</text><text>¥{{money(row.amountCent)}}</text></view><text>{{label(row.state)}} · {{row.quantity?row.quantity+'件':''}}</text><text class="muted">批次 {{row.batchId||'尚未进入执行批次'}}</text><text class="muted">申请：{{date(row.applicationAt)}} · 核准：{{date(row.approvedAt)}}</text><text class="muted">本地回写：{{date(row.succeededAt)}}</text><AppButton class="s45-action" v-if="row.afterSaleId" size="compact" variant="secondary" @click="openSale(row.afterSaleId)">查看关联售后</AppButton></view></BaseCard>
<BaseCard v-if="data.tasks?.length"><text class="section">资金操作进度</text><view v-for="task in data.tasks" :key="task.id" class="record"><view class="row"><text>{{label(task.kind)}} · {{label(task.state)}}</text><text>¥{{money(task.amountCent)}}</text></view><text class="muted">原请求 {{task.requestNo}}</text><text class="muted">成功明细 ¥{{money(task.succeededCent)}} · {{task.applied?'业务已回写':'业务回写待核对'}}</text><text class="muted">渠道受理：{{date(task.acceptedAt)}} · 渠道成功：{{date(task.succeededAt)}}</text><text class="muted">本次观察：{{date(task.observedAt)}}</text><text v-if="task.reason" class="notice">{{task.reason}}</text><view v-for="row in task.receiverDetails||[]" :key="row.detailId" class="record"><text>{{row.account}} · {{label(row.state)}} · ¥{{money(row.amountCent)}}</text><text class="muted">明细 {{row.detailId}}</text><text class="muted">成功时刻：{{date(row.succeededAt)}}</text></view></view><text class="muted">商户只读查看，资金异常由有权平台人员按原请求核实。</text></BaseCard>
<BaseCard v-if="data.exceptions?.some(v=>v.state==='OPEN')"><text class="section">待核实事项</text><text class="error">该订单有资金异常，尚不能认定全部结清。请联系平台核对原交易。</text><view v-for="row in (data.exceptions||[]).filter(v=>v.state==='OPEN')" :key="row.id" class="record"><text>{{row.explanation||'原资金条件待核实'}}</text><text class="muted">已记录 {{row.observationCount==null?'待核实':row.observationCount}} 次观察 · {{date(row.updatedAt)}}</text></view></BaseCard><AppButton class="s45-action" variant="secondary" @click="load">查询最新资金状态</AppButton></template></view></template>
<style scoped lang="scss">@import './stage45.scss';</style>
